import json,re
for f in ["parecer.md","parecer.json","QUESTIONS.md","STATUS.md"]:
    t=open(f"/work/workspace/deliverable/{f}").read()
    bad=[]
    for m in re.findall(r"(S[uú]mula \d+|OJ SDI-1[^\s,;]*|Tema [\d.]+|ARE [\d.]+|Lei [^\s,;]+|ADPF \d+|ADC \d+|S[uú]mula do TST[^\s]*)", t):
        bad.append(m)
    print(f, sorted(set(bad)))
EOF"}
